import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
i=G['Demo pair 1 input']; o=G['Demo pair 1 output']
H,W=len(i),len(i[0])
# find 1-cells; group into adjacent pairs
ones=[(r,c) for r in range(H) for c in range(W) if i[r][c]==1]
pairs=[]; seen=set()
for p in ones:
    if p in seen: continue
    nb=[q for q in ones if abs(q[0]-p[0])+abs(q[1]-p[1])==1 and q!=p]
    if len(nb)==1:
        q=nb[0]; seen.add(p); seen.add(q); pairs.append((p,q))
print(len(pairs))
# check: each pair gets a 3x3 box of 3s centered on pair midpoint? verify
boxcells=set()
for (r1,c1),(r2,c2) in pairs:
    cr=(r1+r2)//2; cc=(c1+c2)//2
    for rr in range(cr-1,cr+2):
        for cc_ in range(cc-1,cc+2):
            if 0<=rr<H and 0<=cc_<W: boxcells.add((rr,cc_))
ok=all((o[r][c]==3 if (r,c) in boxcells else o[r][c]==i[r][c]) for r in range(H) for c in range(W))
print('match' if ok else 'mismatch')

# Print output grid with 3s as 'F' and original 1s as 'o', to see box extents.
for r in range(H):
    print(''.join('F' if o[r][c]==3 else ('o' if i[r][c]==1 else '.') for c in range(W)))

ti=G['Test input']
